import torch

def add_white_patch(img, corner='top-left', size=4):
    """Add a white square patch 1 pixel from the corner"""
    img = img.clone()
    c, h, w = img.shape
    if corner == 'top-left':
        y, x = 1, 1
    elif corner == 'top-right':
        y, x = 1, w - size - 1
    elif corner == 'bottom-left':
        y, x = h - size - 1, 1
    elif corner == 'bottom-right':
        y, x = h - size - 1, w - size - 1
    img[:, y:y+size, x:x+size] = 255  # White patch
    return img

def add_checkerboard_patch(img, corner='top-left', size=4):
    """Add a checkerboard patch 1 pixel from the corner"""
    img = img.clone()
    c, h, w = img.shape
    if corner == 'top-left':
        y, x = 1, 1
    elif corner == 'top-right':
        y, x = 1, w - size - 1
    elif corner == 'bottom-left':
        y, x = h - size - 1, 1
    elif corner == 'bottom-right':
        y, x = h - size - 1, w - size - 1
    # Create checkerboard pattern
    for i in range(size):
        for j in range(size):
            val = 255 if (i + j) % 2 == 0 else 0
            img[:, y+i, x+j] = val
    return img

def add_noise_patch(img, corner='top-left', size=4):
    """Add random black/white noise patch"""
    img = img.clone()
    c, h, w = img.shape
    if corner == 'top-left':
        y, x = 1, 1
    elif corner == 'top-right':
        y, x = 1, w - size - 1
    elif corner == 'bottom-left':
        y, x = h - size - 1, 1
    elif corner == 'bottom-right':
        y, x = h - size - 1, w - size - 1
    # Random noise
    noise = torch.randint(0, 2, (c, size, size)) * 255
    img[:, y:y+size, x:x+size] = noise
    return img

